"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.34662",title:"StreamVibe: Proactive Video Agents for Evolving User Intent",up:240,href:"https://arxiv.org/abs/2610.34662",abstract:'Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., "where should I click next?" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation sam',pdfUrl:"https://arxiv.org/pdf/2610.34662",primaryCategory:"cs.CV",published:"2026-10-26T00:00:00Z"},{id:"2610.34467",title:"DynaFlow: Learning Free-Form Multi-Agent Orchestration",up:183,href:"https://arxiv.org/abs/2610.34467",abstract:"Multi-agent systems often rely on predefined collaboration structures, limiting their ability to adapt to diverse task requirements. We introduce DynaFlow, a framework that integrates free-form executable workflow synthesis into the action space of the main agent. The agent decides when collaboration is needed and generates task-specific programs that coordinate sub-agents through sequential or parallel execution, structured information exchange, and verification. Execution results and traces inform subsequent actions, enabling the agent to adapt collaboration as reasoning progresses. We train",pdfUrl:"https://arxiv.org/pdf/2610.34467",primaryCategory:"cs.MA",published:"2026-10-25T00:00:00Z"},{id:"2610.35845",title:"Work Agents: Systems, Capabilities, and Optimization",up:98,href:"https://arxiv.org/abs/2610.35845",abstract:"As foundation models evolve from information generation to digital work execution, agents are increasingly capable of completing complex tasks across tools, applications, and workflows. However, existing research lacks a unified perspective on how agents reliably accomplish delegated work. To address this gap, we present a work-centric, system-level perspective that views work agents as systems combining foundation models and runtime harnesses to execute tasks in stateful workspaces and deliver verifiable outcomes. We introduce two complementary dimensions, work persistence and work openness, ",pdfUrl:"https://arxiv.org/pdf/2610.35845",primaryCategory:"cs.LG",published:"2026-10-26T00:00:00Z"},{id:"2610.34415",title:"Spatial Audio Generation and Editing with Executable Plans and Self-Distilling Transfusion",up:38,href:"https://arxiv.org/abs/2610.34415",abstract:"Spatial audio authoring coordinates source decisions with soundfield synthesis. For editing, plans specify what to change and retain, while reference audio supplies further acoustic detail. We present AMBIT, a unified framework for native First-Order Ambisonics (FOA) generation and editing with three connected contributions. First, a shared Transfusion backbone couples autoregressive planning with rectified-flow rendering through executable ScenePlans that specify source content, activity, and 3D trajectories. For editing, the plan describes the full target scene, including retained sources; c",pdfUrl:"https://arxiv.org/pdf/2610.34415",primaryCategory:"cs.SD",published:"2026-10-25T00:00:00Z"},{id:"2610.33413",title:"AV-FABLE: Audio-Visual Manipulation Forensics in Long-Form Videos",up:33,href:"https://arxiv.org/abs/2610.33413",abstract:"Localized AI manipulations in long-form videos often affect brief events within otherwise authentic content, making video-level classification insufficient for forensic analysis. Existing audio-visual deepfake benchmarks largely focus on short talking-head clips, while long-form temporal forensics remains predominantly visual. We introduce AV-FABLE, a dual-timeline benchmark for sparse manipulations in open-scene long-form audio-visual videos. AV-FABLE contains 16,650 pristine--manipulated twin pairs (998 hours) created with 27 editing configurations, with separate audio and visual timelines t",pdfUrl:"https://arxiv.org/pdf/2610.33413",primaryCategory:"cs.CV",published:"2026-10-24T00:00:00Z"},{id:"2610.33512",title:"Eat Your Precision: Precision Objective Mitigates Reward Hacking in Rubric-based RL",up:29,href:"https://arxiv.org/abs/2610.33512",abstract:"Rubric-based rewards enable effective reinforcement learning on non-verifiable tasks. However, because these rewards are typically defined as a weighted measure of rubric coverage, models are trained primarily to maximize a recall objective. As a result, RL-trained models produce responses that are more complete but also more verbose and contain more unnecessary or factually incorrect content, leading them to be less preferred than responses from the base model. To address this issue, we present the FORK reward, which jointly optimizes recall and a novel precision objective, which requires eac",pdfUrl:"https://arxiv.org/pdf/2610.33512",primaryCategory:"cs.CL",published:"2026-10-24T00:00:00Z"},{id:"2610.34238",title:"Δτ-Bench: Pushing Agents Toward a Moving Capability",up:21,href:"https://arxiv.org/abs/2610.34238",abstract:"In this paper, we introduce $Δτ$-Bench, an executable agent benchmark that models the structural evolution of large tool ecosystems. In $Δτ$-Bench, independently evolving services continually reshape how tasks can be accomplished: familiar tools may disappear or be replaced, while more efficient alternatives emerge amid overlapping functionality and noisy documentation. Against this moving capability frontier, we evaluate whether agents can proactively discover efficient tool-use paths and promptly revise their accumulated procedural knowledge, bringing together demands that existing benchmark",pdfUrl:"https://arxiv.org/pdf/2610.34238",primaryCategory:"cs.CL",published:"2026-10-25T00:00:00Z"},{id:"2610.33472",title:"Qwen-Image-PE: Learning Visual Design for Text-to-Image Prompt Enhancement",up:20,href:"https://arxiv.org/abs/2610.33472",abstract:"Learning visual design is essential for prompt enhancement (PE) to turn underspecified user requests into coherent visual specifications for text-to-image (T2I) generation. Existing methods preserve user intent and improve overall visual appeal, with less explicit emphasis on fine-grained design dimensions. To address this gap, we introduce Qwen-Image-PE, which learns visual design through two-stage training. Supervised fine-tuning with Caption-Based Reverse Distillation (CRD) uses dense captions of well-designed images as design supervision. Reinforcement learning with Groupwise Design Reward",pdfUrl:"https://arxiv.org/pdf/2610.33472",primaryCategory:"cs.CV",published:"2026-10-24T00:00:00Z"},{id:"2610.31635",title:"HiP3R: Hierarchical Pose Graphs for Long-Horizon 3D Reconstruction",up:19,href:"https://arxiv.org/abs/2610.31635",abstract:"Feed-forward models accurately estimate camera motion and 3D geometry from short video windows. However, computational and memory costs prevent direct inference on sequences containing thousands of frames. Long videos must therefore be processed as overlapping chunks. This division produces independent local reconstructions with inconsistent coordinate frames and duplicate estimates of shared cameras. Achieving global consistency requires propagating constraints from adjacent overlaps and distant revisits across the sequence. This requirement naturally motivates pose graph optimization. Howeve",pdfUrl:"https://arxiv.org/pdf/2610.31635",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.35193",title:"Trustworthy Recursive Self-Improvement in the Era of Large Models: Foundation, Risks, Evaluation and Open Challenges",up:18,href:"https://arxiv.org/abs/2610.35193",abstract:"AI systems built around large models increasingly use experience and feedback to make persistent changes to models, prompts, memories, tools, and workflows. Recursive self-improvement (RSI) extends this process to inductive biases and to the mechanisms that govern future updates, which can themselves be revised and reused across improvement cycles. Yet self-modification alone does not guarantee trustworthy improvement. Reported gains may reflect flawed evaluations, previously acquired capabilities may deteriorate, and compliance with behavioral constraints may weaken. Compromised artifacts or ",pdfUrl:"https://arxiv.org/pdf/2610.35193",primaryCategory:"cs.AI",published:"2026-10-26T00:00:00Z"},{id:"2610.18683",title:"ProAS: A Progress-Aware Advantage Shaping Framework for Multi-Turn Agentic Reinforcement Learning",up:14,href:"https://arxiv.org/abs/2610.18683",abstract:"Reinforcement learning (RL) has emerged as the primary paradigm for optimizing Large Language Model (LLM) agents, yet efficient critic-free algorithms (e.g., GRPO) suffer from a fundamental uniform credit assignment dilemma that broadcasts trajectory-level advantages equally to all actions. Our analysis reveals that this uniformity inherently reinforces structurally unreasonable actions in preferred trajectories and ignores each action's downstream deviations in unpreferred ones. To resolve this without introducing critic overhead, we propose Progress-Aware Advantage Shaping (ProAS), a plug-an",pdfUrl:"https://arxiv.org/pdf/2610.18683",primaryCategory:"cs.LG",published:"2026-10-25T00:00:00Z"},{id:"2610.23928",title:"miniTE: Diagnosing and Bridging the Execution Gap in Native NVFP4 Reinforcement Learning",up:13,href:"https://arxiv.org/abs/2610.23928",abstract:"Native NVFP4 promises to accelerate reinforcement learning (RL) for large language models (LLMs), but achieving stable learning across separate training and sampling engines remains challenging. We show that matching model weights and numerical formats is insufficient to ensure consistent policy evaluation, highlighting the importance of cross-engine numerical execution. We introduce miniTE, a lightweight framework that combines execution diagnostics, cross-engine numerical alignment, and efficient native W4A4 (4-bit weights and activations) GEMM computation for LLM RL. It improves numerical e",pdfUrl:"https://arxiv.org/pdf/2610.23928",primaryCategory:"cs.LG",published:"2026-10-07T00:00:00Z"},{id:"2610.33024",title:"Evolving to Match Capabilities: Improving Harness Self-Evolution via Skill Adaptation",up:12,href:"https://arxiv.org/abs/2610.33024",abstract:"Harness self-evolution offers a practical route for LLM agents to improve from execution experience without updating model parameters. Its effectiveness depends on whether models can successfully act on the guidance provided by their harnesses. However, we find that harness benefits are not uniform across model capabilities: skills that improve stronger models can provide little benefit or even degrade performance for weaker ones. Across seven models and three benchmarks, we identify 103 task-skill pairs where skills improve GPT-5.6-luna by 31.1 points but degrade Gemma-4-E4B by 8.8 points. In",pdfUrl:"https://arxiv.org/pdf/2610.33024",primaryCategory:"cs.LG",published:"2026-10-10T00:00:00Z"},{id:"2610.35518",title:"S3AC: Stabilized, Selective, and Scalable Actor-Critic for LLM Reasoning",up:12,href:"https://arxiv.org/abs/2610.35518",abstract:"Critic-free methods are widely used in reinforcement learning with verifiable rewards (RLVR) for long chain-of-thought (CoT) reasoning, avoiding difficult and costly critic training. Common alternatives lack token-level credit assignment and typically rely on grouped rollouts to estimate prompt-specific baselines. A critic can address both limitations, but long-CoT critic training is hindered by insufficient coverage of trajectories with diverse lengths and early gradients dominated by the newly initialized value head. We introduce S3AC (Stabilized, Selective, and Scalable Actor-Critic) for LL",pdfUrl:"https://arxiv.org/pdf/2610.35518",primaryCategory:"cs.LG",published:"2026-10-26T00:00:00Z"},{id:"2610.33845",title:"Build, Don't Play: Self-Improving LLM Research Agents Develop a Hearthstone Battlegrounds AI That Rivals Top Players",up:11,href:"https://arxiv.org/abs/2610.33845",abstract:"Can LLM agents carry a hard real-world problem from raw data to a system that holds its own against people? We study this in Hearthstone Battlegrounds, an eight-player auto-battler with stochastic shops and battles, hidden information and nearly a thousand interacting cards. We present AutoTavern, a self-improving research system: specialised LLM research agents share a typed research memory, every claim passes verification gates, and live games close the loop, so the agents improve the simulator, opponents and policy and, from the same feedback, their own research process; a human sets goals ",pdfUrl:"https://arxiv.org/pdf/2610.33845",primaryCategory:"cs.AI",published:"2026-10-24T00:00:00Z"},{id:"2610.31309",title:"Extreme Compression of Per-Layer Embeddings via Cross-Layer Latent Vector Quantization",up:10,href:"https://arxiv.org/abs/2610.31309",abstract:"Scaling embedding capacity alongside Transformer computation is an emerging trend in language models. This trend makes high compression rates increasingly useful. Hence, we study extreme compression of Per-Layer Embeddings (PLE), which follow this trend and account for 35.2% of the parameters of Gemma 4 E4B. At such rates, conventional quantizers give each token-layer vector its own code of only a few bytes. We instead develop OPTIC (Output-Path-fitted, Token-shared Indexed Codes), which stores one quantized code tuple per token and decodes it at every layer with a layer-specific affine decode",pdfUrl:"https://arxiv.org/pdf/2610.31309",primaryCategory:"cs.LG",published:"2026-10-22T00:00:00Z"},{id:"2610.33079",title:"Rethinking Video Storage for AI Training: Breaking Cross-Frame Dependencies for Efficient Random Access",up:10,href:"https://arxiv.org/abs/2610.33079",abstract:"Large-scale AI training increasingly relies on massive video datasets with random temporal sampling patterns. However, existing video storage paradigms are optimized for sequential playback and employ sophisticated inter-frame reference structures to maximize compression efficiency. When applied to the random-sampling workloads of AI training, these paradigms face substantial decoding-efficiency bottlenecks. Workarounds such as independent JPEG frames and short groups of pictures (GOPs) reduce decoding work at the cost of larger storage and transfer volumes. In this paper, we identify two sour",pdfUrl:"https://arxiv.org/pdf/2610.33079",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.29915",title:"CausalAlign: Causal Alignment of Video Generation Models for Consistent Ego-Motion",up:9,href:"https://arxiv.org/abs/2610.29915",abstract:"Diffusion-based video generation models (VGMs) can produce visually plausible videos, yet their camera ego-motion often drifts over long horizons. Camera ego-motion determines how the viewpoint changes between frames and is essential for maintaining consistent geometry and trajectories. To address this problem, we propose CausalAlign, a causal alignment framework with two components. First, we diagnose how precise ego motion is represented, used, and retained within VGMs using linear probes and causal interventions, revealing a rise-and-fall pattern during denoising. Second, we strengthen ego-",pdfUrl:"https://arxiv.org/pdf/2610.29915",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.34356",title:"RynnVLA-Latent: Scaling Robotic Manipulation Foundation Models with 3D-Grounded Latent Actions",up:9,href:"https://arxiv.org/abs/2610.34356",abstract:"Scaling vision-language-action (VLA) models is constrained by scarce action-labeled demonstrations and incompatible control spaces across robot embodiments. We present RynnVLA-Latent, a framework that turns heterogeneous interaction videos into scalable supervision for robot policy pretraining. At its core, RynnLAM learns continuous, 3D-grounded latent actions from visual transitions without requiring native robot controls. By combining residual future-feature prediction, camera-compensated 3D-flow supervision, and camera-motion decoupling, RynnLAM encourages representations that capture contr",pdfUrl:"https://arxiv.org/pdf/2610.34356",primaryCategory:"cs.RO",published:"2026-10-25T00:00:00Z"},{id:"2610.35385",title:"EmbodiedLab: Benchmarking Embodied Agents That Act to Know",up:9,href:"https://arxiv.org/abs/2610.35385",abstract:"Embodied agents are expected to accomplish real-world goals by deciding for themselves how and when to interact with their surroundings. For many such goals, changing the physical state of the world is the means rather than the end: the agent changes the state of a system through interaction, observes the feedback, and explores until it either achieves the goal itself (e.g., discovering physical laws) or learns what the goal requires; it acts to know. Manipulation benchmarks stop at acting to change, with the target state given; scientific discovery benchmarks evaluate knowing but replace phys",pdfUrl:"https://arxiv.org/pdf/2610.35385",primaryCategory:"cs.RO",published:"2026-10-26T00:00:00Z"},{id:"2610.34634",title:"AgentProofBench: Benchmarking Reusable Verifiers for Web Agents",up:7,href:"https://arxiv.org/abs/2610.34634",abstract:"Reusable Web-agent verification requires a rule to follow changing requirements and support subsequent execution. We introduce AgentProofBench, which connects paired tests of a frozen acceptance rule to execution from identical saved openings. The resource spans 97 tasks, 79 families, and four Web services. Experiments with DeepSeek Flash/Pro establish two linked measurements. Across 48 families, complete-panel and decision-replay tests retain 82/96 Flash and 79/96 Pro source programs; paired reuse-rebuild BA intervals are [-5.47, 1.57] and [-10.16, 0.00] percentage points. Across 22 execution",pdfUrl:"https://arxiv.org/pdf/2610.34634",primaryCategory:"cs.MA",published:"2026-10-25T00:00:00Z"},{id:"2610.34654",title:"Thinking-in-Bets at Test Time Reduces Sycophantic Revisions in LLM Agents",up:7,href:"https://arxiv.org/abs/2610.34654",abstract:"Language model agents often abandon correct work when a user challenges it, yet simply telling them to stand firm makes them ignore real mistakes. Once an agent reads a complaint, it tends to discount its own earlier checks in order to agree with the user. We introduce Thinking-in-Bets, a training-free method in which an agent writes a short private record of its main claims, the checks supporting them, and its confidence before reading user feedback. When challenged, the agent consults this Claim Checklist to keep verified work intact while investigating uncertain or newly challenged parts. W",pdfUrl:"https://arxiv.org/pdf/2610.34654",primaryCategory:"cs.SE",published:"2026-10-26T00:00:00Z"},{id:"2610.34735",title:"iPrefBench: A User-Centric Benchmark for Personalized Mobile Use Agents",up:7,href:"https://arxiv.org/abs/2610.34735",abstract:"An agent that truly knows and acts on behalf of its user has been a long-standing promise of AI assistants. Computer-use agents bring this promise within reach by capably executing fully specified tasks across apps. However, real-world user requests are often underspecified. To act correctly for the particular user, an agent must infer some missing information from the user's activity history and ask for other information that only the user can provide, without making unsupported assumptions or burdening the user with unnecessary questions. We present iPrefBench, a benchmark for evaluating the",pdfUrl:"https://arxiv.org/pdf/2610.34735",primaryCategory:"cs.CL",published:"2026-10-26T00:00:00Z"},{id:"2610.35001",title:"More Memory, Better Videos? A Controlled Study of Visual Memory in Long-Video Generation",up:7,href:"https://arxiv.org/abs/2610.35001",abstract:"Long-video generators increasingly retrieve past visual observations to prevent identity drift. The intuition is compelling: more access to history should make future video more consistent. But an image can be faithful to the past and wrong for the present. Does visual memory always improve the generated story? We investigate this question through VMem-Bench, a two-track diagnostic study. Track-A measures which references are selected from 92 real films (16,548 segments), before generation and without generator confounds. Track-B compares four retrieval policies with no-memory and gold-informe",pdfUrl:"https://arxiv.org/pdf/2610.35001",primaryCategory:"cs.CV",published:"2026-10-26T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W7221316450",title:"FHIR-AgentEval: a modular sandbox for benchmarking clinical LLM agents with memory-augmented configurations",up:0,href:"https://doi.org/10.1038/s41746-026-03348-0",doi:"https://doi.org/10.1038/s41746-026-03348-0",year:2026,openalexId:"https://openalex.org/W7221316450"}]}}]);